def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount* using unlimited coins of given denominations.
    If impossible, return -1.
    Uses DP with O(amount * len(coins)) time.
    """
    # Edge cases
    if amount < 0:
        return -1
    # DP array where dp[i] = min coins for amount i
    # Initialize with a large sentinel value (amount+1 is sufficient as max needed)
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                # If we can use coin c, consider using it
                if dp[i - c] + 1 < dp[i]:
                    dp[i] = dp[i - c] + 1
    return dp[amount] if dp[amount] != amount + 1 else -1

