def solve(path: str) -> str:
    """Simplify an absolute Unix path.
    Resolve '.' and '..', collapse multiple slashes, and remove any trailing slash.
    The root '/' is returned for empty or fully resolved paths.
    """
    stack: list[str] = []
    for part in path.split('/'):
        if part == '' or part == '.':
            # skip empty parts caused by '//' and current directory marker
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            # treat any other string (including names with dots) as a directory
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

