def solve(m):
    if not m:
        return 1
    n = len(m)
    a = [list(row) for row in m]
    det = 1
    for col in range(n):
        pivot = None
        for r in range(col, n):
            if a[r][col] != 0:
                pivot = r
                break
        if pivot is None:
            return 0
        if pivot != col:
            a[col], a[pivot] = a[pivot], a[col]
            det = -det
        det *= a[col][col]
        inv = a[col][col]
        for r in range(col + 1, n):
            f = a[r][col]
            if f:
                for c in range(col, n):
                    a[r][c] = a[r][c] * inv - a[col][c] * f
    return det

