            return
        if seen[r][c] or grid[r][c] in ('0', 0):
            return
        seen[r][c] = True
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] in ('1', 1) and not seen[r][c]:
