def solve(grid):
    """Count the number of islands (connected components of 1's) in a grid.
    The grid may be non‑rectangular; each row is processed with its own length.
    Cells are connected orthogonally (up, down, left, right).
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def neighbors(i, j):
        # four directions
        for di, dj in ((-1,0),(1,0),(0,-1),(0,1)):
            ni, nj = i+di, j+dj
            if 0 <= ni < rows and 0 <= nj < len(grid[ni]):
                yield ni, nj
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            ci, cj = stack.pop()
            if (ci, cj) in visited:
                continue
            if not grid[ci][cj]:
                continue
            visited.add((ci, cj))
            for ni, nj in neighbors(ci, cj):
                if (ni, nj) not in visited and grid[ni][nj]:
                    stack.append((ni, nj))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

