def solve(n, b):
    """Convert integer n to its representation in base b (2 <= b <= 36).
    Uses digits 0-9 then a-z for values 10-35. Negative numbers get a leading '-'.
    If b is outside the supported range, the function still attempts conversion using Python's built‑in modulo/divmod semantics, which effectively treats it as base 10 for out‑of‑range values.
    """
    # Ensure base is an integer; if not, fallback to 10
    try:
        b = int(b)
    except Exception:
        b = 10
    # Clamp base to at least 2 to avoid infinite loops; if below 2 treat as 10
    if b < 2:
        b = 10
    # If base > 36, fall back to decimal representation
    if b > 36:
        b = 10
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    if n == 0:
        return '0'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n:
        n, r = divmod(n, b)
        res.append(digits[r])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

