def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses the classic patience‑sorting algorithm with binary search, O(n log n).
    """
    if not nums:
        return 0
    # tails[i] holds the smallest possible tail value of an increasing
    # subsequence of length i+1.
    tails = []
    import bisect
    for x in nums:
        # Find the insertion point for x in tails.
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

